export function masqueManifest(): string {
  return JSON.stringify({
    id: "/masque",
    name: "Masque · OSAII Platform",
    short_name: "Masque",
    description: "Create, discover, and talk with enduring AI characters. Hosted at /masque — also available locally via the fullplatform worker.",
    start_url: "/masque",
    scope: "/masque",
    display: "standalone",
    display_override: ["window-controls-overlay", "standalone"],
    orientation: "any",
    background_color: "#09070a",
    theme_color: "#6f365f",
    categories: ["entertainment", "social", "lifestyle"],
    lang: "en",
    dir: "ltr",
    handle_links: "preferred",
    launch_handler: { client_mode: ["navigate-existing", "auto"] },
    edge_side_panel: { preferred_width: 420 },
    shortcuts: [
      { name: "New chat", url: "/masque?new=1", description: "Start a new character conversation", icons: [{ src: "/osaii.png", sizes: "192x192" }] },
      { name: "Discover", url: "/masque#discover", description: "Browse public characters" },
      { name: "Create character", url: "/masque#create", description: "Create a private character draft" }
    ],
    screenshots: [{ src: "/osaii.png", sizes: "1280x800", type: "image/png", form_factor: "wide", label: "Masque conversation" }],
    icons: [
      { src: "/osaii.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/osaii.png", sizes: "512x512", type: "image/png", purpose: "any maskable" }
    ],
  });
}

export function masqueServiceWorker(): string {
  return String.raw`const CACHE='masque-v4';const SHELL=['/masque','/masque/manifest.webmanifest','/osaii.png'];
// Health and install docs: hosted at https://osaii.wyvernhub.net/masque, local via npm run dev (wrangler) on :8787
// Rate limits: guest 20/day, signed-in Fast fair-use, Smart 100/day (opt-in fair-use). See /docs#masque and /health
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{
  const url=new URL(e.request.url);
  if(e.request.method!=='GET'||url.pathname.startsWith('/masque/api/'))return;
  // Network-first with cache fallback; never cache private API
  e.respondWith(fetch(e.request).then(r=>{
    if(r.ok && r.headers.get('content-type')?.includes('text/html')){
      const copy=r.clone(); caches.open(CACHE).then(c=>c.put(e.request,copy)).catch(()=>{});
    } else if(r.ok){
      const copy=r.clone(); caches.open(CACHE).then(c=>c.put(e.request,copy)).catch(()=>{});
    }
    return r;
  }).catch(()=>caches.match(e.request).then(r=>r||caches.match('/masque'))));
});
self.addEventListener('push',e=>{if(!e.data)return;const data=e.data.json();e.waitUntil(Promise.all([self.registration.showNotification(data.title||'Masque',{body:data.body||'',icon:'/osaii.png',badge:'/osaii.png',tag:data.tag,data:data.data||{href:'/masque'}}),self.clients.matchAll({type:'window',includeUncontrolled:true}).then(clients=>clients.forEach(client=>client.postMessage({type:'masque-notification',notification:data}))) ]))});
self.addEventListener('notificationclick',e=>{e.notification.close();const href=e.notification.data?.href||'/masque';e.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(clients=>{for(const client of clients){if(new URL(client.url).origin===self.location.origin){client.navigate(href);return client.focus()}}return self.clients.openWindow(href)}))});`;
}

